import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Install / console not opening","description":"Which Release archive to download, why an old link 404s, GLIBC errors, checksum verification, DSN, Redis startup Ping, empty static_dir, self-built binary without yarn build.","frontmatter":{"title":"Install / console not opening","description":"Which Release archive to download, why an old link 404s, GLIBC errors, checksum verification, DSN, Redis startup Ping, empty static_dir, self-built binary without yarn build."},"headers":[],"relativePath":"en/faq/install.md","filePath":"en/faq/install.md","lastUpdated":1790057721000}`),a={name:`en/faq/install.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="install-console-not-opening" tabindex="-1">Install / console not opening <a class="header-anchor" href="#install-console-not-opening" aria-label="Permalink to “Install / console not opening”">​</a></h1><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>No idea which archive to download</td><td>On the Release page pick by prefix: <code>KiriVers-&lt;OS&gt;-&lt;Arch&gt;-</code>, see <a href="/en/guide/install/#releases-files">Picking a Release asset</a>. The extracted executable is named <code>kirivers-&lt;os&gt;-&lt;arch&gt;</code></td></tr><tr><td>Yesterday&#39;s download link 404s today</td><td>Expected: the last six characters of the archive name are the binary&#39;s content hash, so they change every release. Bookmark the Release page, not an individual file link</td></tr><tr><td>Linux reports <code>GLIBC_x.y not found</code></td><td>The <code>x86</code>, <code>armv7</code> and <code>riscv64</code> archives are cross-built against glibc ≥ 2.39. On older systems switch to <a href="/en/guide/install/docker">Docker</a> (musl, amd64/arm64 only) or build from source</td></tr><tr><td>How do I verify a checksum</td><td><code>sha256sum -c SHA256SUMS.txt</code> (the first section covers the 11 uploaded files). The second section records the in-archive binaries as <code>#</code> comments; extract and compare them yourself</td></tr><tr><td>Process exits immediately</td><td><code>postgres.dsn</code>; whether one of the five log streams has both sinks off; <code>changelog.default_entries &gt; max_entries</code></td></tr><tr><td><code>cache.driver=redis</code> will not start</td><td>Startup Ping failed. Start Redis or switch back to <code>memory</code></td></tr><tr><td>Wrong port</td><td>Client <code>:8080</code>, admin <code>:8081</code></td></tr><tr><td>JSON instead of the login page</td><td><code>admin.enabled</code>; <code>static_dir: &quot;&quot;</code> disables the UI; a self-built binary that never built the admin console (no embedded <code>index.html</code>)</td></tr><tr><td>Official Release shows no UI</td><td>Official binaries already embed the console; copying <code>frontend/dist</code> is unnecessary. Check that <code>static_dir</code> was not set to the empty string</td></tr></tbody></table><p>On Windows use <a href="/en/guide/install/manual">manual install</a>; the one-click script only supports Linux with apt/yum. <code>static_dir</code> is the admin console; the VitePress docs <code>dist</code> is not the console.</p>`,3)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};